	StepReqAccountLoginPackage::StepReqAccountLoginPackage()
	{
		Head.PackageID = PackageID;
	}
	StepReqAccountLoginPackage* StepReqAccountLoginPackage::Allocate()
	{
		return ::Allocate<StepReqAccountLoginPackage>();
	}
	void StepReqAccountLoginPackage::Free()
	{
		SessionID = 0;
		memset(IPAddress, 0, sizeof(IPAddressType));
		memset(&Head, 0, sizeof(Head));
		memset(&Tail, 0, sizeof(Tail));
		Head.PackageID = PackageID;
		if (ReqAccountLogin != nullptr)
		{
			::Free<StepReqAccountLogin>(ReqAccountLogin);
			ReqAccountLogin = nullptr;
		}
		MemCacheTemplateSingleton<StepReqAccountLoginPackage>::GetInstance().Free(this);
	}
	void StepReqAccountLoginPackage::Prepare(SessionIDType sessionID, bool messageChain, int msgSeqNum)
	{
		SessionID = sessionID;
		Head.MessageChain = messageChain;
		Head.MsgSeqNum = msgSeqNum;
	}
	int StepReqAccountLoginPackage::ToProtocolStream(char* buff, int size) const
	{
		char* ppos = buff;
		if (ReqAccountLogin != nullptr)
		{
			WriteHexString(ppos, StepHeadIDs::FieldStart, StepReqAccountLogin::FieldID);
			if (strlen(ReqAccountLogin->AccountID) >= sizeof(ReqAccountLogin->AccountID))
			{
				ReqAccountLogin->AccountID[sizeof(ReqAccountLogin->AccountID) - 1] = 0;
			}
			WriteString(ppos, StepItemIDs::AccountID, ReqAccountLogin->AccountID);
			if (strlen(ReqAccountLogin->Password) >= sizeof(ReqAccountLogin->Password))
			{
				ReqAccountLogin->Password[sizeof(ReqAccountLogin->Password) - 1] = 0;
			}
			WriteString(ppos, StepItemIDs::Password, ReqAccountLogin->Password);
			WriteHexString(ppos, StepHeadIDs::FieldEnd, StepReqAccountLogin::FieldID);
		}
		return int(ppos - buff);
	}
	bool StepReqAccountLoginPackage::FromProtocolStream(char* buff, int startIndex, int endIndex)
	{
		while (startIndex < endIndex)
		{
			unsigned short fieldID;
			int fieldStartIndex;
			int fieldEndIndex;
			if (GetNextFieldZone(buff, startIndex, endIndex, fieldID, fieldStartIndex, fieldEndIndex))
			{
				int itemStartIndex = fieldStartIndex;
				switch (fieldID)
				{
				case StepReqAccountLogin::FieldID:
				{
					ReqAccountLogin = ::Allocate<StepReqAccountLogin>();
					memset(ReqAccountLogin, 0, sizeof(*ReqAccountLogin));
					while (itemStartIndex < fieldEndIndex)
					{
						unsigned short  itemID;
						std::string value;
						int sohIndex;
						if (GetNext(buff, itemStartIndex, fieldEndIndex, itemID, value, sohIndex))
						{
							switch (itemID)
							{
							case StepHeadIDs::FieldStart:
							case StepHeadIDs::FieldEnd:
								break;
							case StepItemIDs::AccountID:
							{
								size_t len = value.length() >= sizeof(ReqAccountLogin->AccountID) ? sizeof(ReqAccountLogin->AccountID) - 1 : value.length();
								memcpy(ReqAccountLogin->AccountID, value.c_str(), len);
								break;
							}
							case StepItemIDs::Password:
							{
								size_t len = value.length() >= sizeof(ReqAccountLogin->Password) ? sizeof(ReqAccountLogin->Password) - 1 : value.length();
								memcpy(ReqAccountLogin->Password, value.c_str(), len);
								break;
							}
							default:
								WriteLog(LogLevel::Warning, "Unexpected ItemID:0x%X for StepReqAccountLogin FieldID:0x%X, Please Check ApiVersion.", itemID, fieldID);
								return false;
							}
							itemStartIndex = sohIndex + 1;
						}
						else
						{
							WriteLog(LogLevel::Warning, "GetNext Failed For StepReqAccountLoginPackage FieldID:0x%X", fieldID);
							return false;
						}
					}
					break;
				}
				default:
					WriteLog(LogLevel::Warning, "Unexpected FieldID:0x%X, Please Check Api Version.", fieldID);
					return false;
				}
				startIndex = fieldEndIndex;
			}
			else
			{
				WriteLog(LogLevel::Warning, "GetNextFieldZone Failed For StepReqAccountLoginPackage");
				return false;
			}
		}
		return true;
	}
	const char* StepReqAccountLoginPackage::GetDebugString() const
	{
		if (ReqAccountLogin == nullptr)
		{
			return "";
		}
		int index = 0;
		if (ReqAccountLogin != nullptr)
		{
			index += sprintf(t_StepPackageStringBuffer + index, "StepReqAccountLoginPackage:AccountID:[%s], Password:[%s]", ReqAccountLogin->AccountID, ReqAccountLogin->Password);
		}
		return t_StepPackageStringBuffer;
	}
